def orbit(r,c,n=24):
 return {(r,c),(c,r),(n-1-r,c),(r,n-1-c),(n-1-r,n-1-c),(n-1-c,n-1-r),(c,n-1-r),(n-1-c,r)}
for gname,g in [('demo',demo_in),('test',test)]:
 unresolved=[]; conflicts=[]
 for r,c in [(r,c) for r in range(24) for c in range(24) if g[r][c]==2]:
  vals={(g[x][y],x,y) for x,y in orbit(r,c) if g[x][y]!=2}
  if len(vals)==0: unresolved.append((r,c))
  elif len({v for v,_,_ in vals})>1: conflicts.append((r,c,vals))
 print(gname,'unresolved',unresolved,'conflicts',len(conflicts),conflicts[:4])
